package com.andye.warmod.phalanx.client;import com.andye.warmod.block.entity.PhalanxBlockEntity;import com.andye.warmod.warhead.client.render.WarheadRenderPipelines;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.renderer.feature.ModelFeatureRenderer;import net.minecraft.client.renderer.state.level.CameraRenderState;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;
public final class PhalanxBlockEntityRenderer implements BlockEntityRenderer<PhalanxBlockEntity,PhalanxRenderState>{public PhalanxBlockEntityRenderer(BlockEntityRendererProvider.Context c){}@Override public PhalanxRenderState createRenderState(){return new PhalanxRenderState();}@Override public void extractRenderState(PhalanxBlockEntity be,PhalanxRenderState s,float partial,Vec3 camera,ModelFeatureRenderer.@Nullable CrumblingOverlay overlay){BlockEntityRenderer.super.extractRenderState(be,s,partial,camera,overlay);s.yaw=be.yaw();s.pitch=be.pitch();s.spin=be.barrelSpin()*(be.getLevel()==null?0:be.getLevel().getGameTime()+partial);s.firing=be.status()==com.andye.warmod.phalanx.PhalanxGunStatus.FIRING;}@Override public void submit(PhalanxRenderState s,PoseStack pose,SubmitNodeCollector collector,CameraRenderState camera){collector.submitCustomGeometry(pose,WarheadRenderPipelines.PROJECTILE,(p,b)->PhalanxTurretMesh.render(p,b,s.lightCoords,s.yaw,s.pitch,s.spin));}@Override public int getViewDistance(){return 256;}}
